WITH templates(event_key,title,body,choices) AS (
VALUES
('mate_rival_challenge','A disputa aparece no treino','Um companheiro da sua posição comenta que os próximos treinos podem definir quem começa jogando.',
'[{"key":"embrace","label":"Dizer que quer a disputa forte e que cada treino deve valer como teste.","reply":"Então vamos elevar o nível. Quem estiver melhor joga.","result":"A concorrência ficou mais aberta e intensa.","reply_speaker":"Companheiro","effects":{"ambition":2,"pressure":1,"rivalry":1,"teammate_relation":-1}},{"key":"measure","label":"Responder que prefere comparar desempenho no conjunto da semana, não em um treino só.","reply":"Justo. Então vamos ver quem mantém o nível por mais tempo.","result":"A disputa ganhou um tom mais calculado.","reply_speaker":"Companheiro","effects":{"pressure":-1,"leadership":1,"teammate_relation":0}},{"key":"pair","label":"Propor que vocês treinem juntos e se cobrem nas mesmas situações.","reply":"Pode ser. Se um achar defeito no outro, os dois melhoram.","result":"Competição e cooperação passaram a coexistir.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"ambition":-1}}]'::jsonb),
('mate_rival_contact','Uma dividida muda o clima','Depois de uma disputa mais forte pela bola, o companheiro que concorre com você pergunta se aquilo foi intensidade ou recado.',
'[{"key":"own","label":"Assumir que foi forte e dizer que não pretende diminuir a intensidade.","reply":"Beleza. Então eu também vou entrar em todas.","result":"O treino ganhou um duelo particular dentro dele.","reply_speaker":"Companheiro","effects":{"ambition":2,"rivalry":1,"teammate_relation":-2}},{"key":"technical","label":"Explicar a leitura do lance e discutir como os dois poderiam disputar melhor a bola.","reply":"Vendo assim, eu também cheguei atrasado. Na próxima muda o ângulo.","result":"A tensão virou discussão técnica.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"leadership":1,"pressure":1}},{"key":"reset","label":"Dizer que foi lance de treino e voltar imediatamente para a atividade.","reply":"Fechado. Bola para frente.","result":"O episódio ficou sem conclusão emocional clara.","reply_speaker":"Companheiro","effects":{"pressure":-1,"teammate_relation":0,"ambition":-1}}]'::jsonb),
('mate_tactical_disagreement','Vocês enxergaram a jogada diferente','Um companheiro diz que sua movimentação fechou o espaço que ele queria atacar e propõe outra leitura para o lance.',
'[{"key":"defend_read","label":"Explicar por que você atacou aquele espaço e manter sua leitura.","reply":"Entendi o que você viu. No próximo lance eu vou observar se a defesa reage igual.","result":"As duas leituras ficaram na mesa.","reply_speaker":"Companheiro","effects":{"ambition":1,"teammate_relation":-1,"pressure":0}},{"key":"adapt","label":"Testar a leitura dele na próxima repetição e comparar o resultado.","reply":"Boa. Depois fazemos uma do seu jeito e outra do meu.","result":"A divergência virou experimento de treino.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"leadership":1,"fatigue":1}},{"key":"alternate","label":"Sugerir alternar quem ocupa o corredor para a defesa não saber o padrão.","reply":"Isso pode funcionar. Se alternar, ninguém fica previsível.","result":"Vocês criaram uma solução mais flexível.","reply_speaker":"Companheiro","effects":{"teammate_relation":1,"ambition":1,"pressure":1}}]'::jsonb),
('mate_training_tip','Um detalhe técnico chama atenção','Durante uma pausa, um companheiro aponta um detalhe pequeno no seu gesto técnico que pode mudar a próxima repetição.',
'[{"key":"try_now","label":"Testar a sugestão imediatamente nas próximas bolas.","reply":"É isso, tenta sentir a diferença no contato.","result":"Você transformou a conversa em repetição prática.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"fatigue":1,"ambition":1}},{"key":"compare","label":"Pedir para ele mostrar como faz e comparar os dois movimentos.","reply":"Olha meu apoio aqui. O seu é mais rápido, mas abre mais o corpo.","result":"A conversa virou troca técnica entre estilos diferentes.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"sociability":1,"pressure":1}},{"key":"keep_style","label":"Agradecer a observação, mas continuar trabalhando o movimento que você já treina.","reply":"Tranquilo. Se é o que você vem repetindo, faz sentido manter a referência.","result":"Você preservou sua própria rotina técnica.","reply_speaker":"Companheiro","effects":{"ambition":1,"teammate_relation":0,"pressure":-1}}]'::jsonb),
('mate_extra_session_invite','Surge um treino depois do treino','Um companheiro pergunta se você fica mais alguns minutos para repetir uma situação específica depois da atividade coletiva.',
'[{"key":"stay","label":"Ficar e transformar a sessão em uma disputa curta de execução.","reply":"Fechado. Dez bolas para cada um e sem desculpa.","result":"A sessão extra ficou competitiva e exigente.","reply_speaker":"Companheiro","effects":{"ambition":2,"fatigue":2,"rivalry":1,"teammate_relation":1}},{"key":"cooperate","label":"Ficar, mas usar o tempo para vocês corrigirem um ao outro.","reply":"Melhor. Um observa enquanto o outro executa.","result":"O trabalho extra ganhou caráter cooperativo.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"fatigue":2}},{"key":"decline","label":"Dizer que hoje vai preservar o corpo e combinar outra sessão em um dia mais leve.","reply":"Sem problema. Melhor fazer quando der para treinar direito.","result":"Você priorizou a gestão de carga sem fechar a porta.","reply_speaker":"Companheiro","effects":{"pressure":-1,"fatigue":-1,"teammate_relation":0,"ambition":-1}}]'::jsonb),
('mate_rival_respect','O concorrente reconhece seu momento','Depois do treino, o jogador que disputa sua posição admite que você está numa sequência forte.',
'[{"key":"return_respect","label":"Reconhecer que ele também está te obrigando a jogar num nível mais alto.","reply":"Então continua assim. Eu também não quero ganhar vaga fácil.","result":"A rivalidade ganhou respeito sem perder intensidade.","reply_speaker":"Rival","effects":{"teammate_relation":3,"ambition":1}},{"key":"keep_edge","label":"Agradecer e responder que ainda quer abrir distância na disputa.","reply":"Eu imaginava. Então vou ter que acompanhar.","result":"O respeito veio acompanhado de mais competição.","reply_speaker":"Rival","effects":{"ambition":2,"pressure":1,"rivalry":1,"teammate_relation":-1}},{"key":"downplay","label":"Dizer que sequência muda rápido e que você não está tratando a vaga como garantida.","reply":"É. Duas semanas ruins mudam tudo aqui.","result":"A conversa terminou em cautela competitiva.","reply_speaker":"Rival","effects":{"pressure":-1,"teammate_relation":1,"ambition":-1}}]'::jsonb),
('mate_rival_media','A imprensa colocou vocês frente a frente','Um companheiro mostra uma matéria comparando vocês dois na mesma posição e pergunta o que você achou.',
'[{"key":"fuel","label":"Dizer que a comparação serve como combustível e que quer terminar na frente.","reply":"Imaginei que você ia usar isso assim. Eu também vou.","result":"A matéria virou combustível para os dois.","reply_speaker":"Rival","effects":{"ambition":2,"pressure":2,"rivalry":1,"teammate_relation":-1}},{"key":"ignore_rank","label":"Dizer que a comparação não mede as funções diferentes que cada um cumpre.","reply":"Também acho. Eles transformam tudo em ranking.","result":"Vocês questionaram a narrativa externa sem encerrar a competição.","reply_speaker":"Rival","effects":{"pressure":-2,"teammate_relation":2,"ambition":-1}},{"key":"analyse","label":"Usar a matéria para discutir em que situações cada um está rendendo melhor.","reply":"Essa parte aqui faz sentido. Seu mapa de ações está diferente do meu.","result":"A comparação virou análise de desempenho.","reply_speaker":"Rival","effects":{"teammate_relation":1,"leadership":1,"pressure":1}}]'::jsonb),
('mate_pass_complaint','Ele queria a bola naquele lance','Um companheiro volta a um lance recente e diz que fez uma corrida que você não aproveitou.',
'[{"key":"explain","label":"Explicar o que você enxergou e por que escolheu outra ação.","reply":"Certo. Pelo seu ângulo dava mesmo para ver outra coisa.","result":"Vocês ficaram com leituras diferentes, mas mais claras.","reply_speaker":"Companheiro","effects":{"teammate_relation":1,"ambition":1,"pressure":1}},{"key":"ask_signal","label":"Combinar um sinal para você perceber aquela corrida mais cedo na próxima vez.","reply":"Fechado. Quando eu sair por dentro, vou chamar antes.","result":"A reclamação virou um código entre vocês.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"leadership":1}},{"key":"challenge","label":"Responder que, se ele repetir a corrida com mais vantagem, você tenta o passe.","reply":"Então presta atenção na próxima. Eu vou atacar o espaço mais cedo.","result":"Os dois colocaram exigência um sobre o outro.","reply_speaker":"Companheiro","effects":{"ambition":2,"teammate_relation":-1,"rivalry":1}}]'::jsonb),
('mate_defensive_effort','Um companheiro cobra o trabalho sem bola','Durante a revisão de um lance, um companheiro diz que precisou cobrir seu setor e pergunta como vocês vão dividir essa responsabilidade.',
'[{"key":"commit","label":"Dizer que vai recompor mais cedo quando ele avançar.","reply":"Isso já resolve. Se eu passar, você fecha; se você for, eu seguro.","result":"Vocês definiram uma responsabilidade mais clara.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"discipline":1,"fatigue":1}},{"key":"tradeoff","label":"Explicar que às vezes ficar alto é parte da ameaça e propor escolher os momentos juntos.","reply":"Faz sentido, mas me avisa quando for ficar. Aí eu não saio ao mesmo tempo.","result":"A equipe pode ganhar transição, mas exige coordenação.","reply_speaker":"Companheiro","effects":{"ambition":1,"teammate_relation":1,"pressure":1}},{"key":"hold_role","label":"Dizer que prefere manter sua função e levar a dúvida ao treinador para ajustar o setor.","reply":"Beleza. Melhor alinhar do que cada um interpretar de um jeito.","result":"A decisão tática foi devolvida à comissão.","reply_speaker":"Companheiro","effects":{"teammate_relation":0,"discipline":1,"ambition":-1}}]'::jsonb),
('mate_penalty_talker','O assunto vira pressão','No vestiário, um companheiro pergunta como você lida com um lance decisivo quando sabe que todo mundo está olhando.',
'[{"key":"routine","label":"Dizer que tenta repetir exatamente a mesma rotina de treino.","reply":"Eu faço parecido. Quanto menos coisa inventar na cabeça, melhor.","result":"Você tratou pressão como rotina.","reply_speaker":"Companheiro","effects":{"pressure":-2,"discipline":1,"ambition":-1}},{"key":"seek_moment","label":"Dizer que gosta de sentir o peso do momento e usar isso para se concentrar.","reply":"Então você é dos que cresce com barulho. Quero ver quando vier a chance.","result":"A pressão foi assumida como parte da experiência.","reply_speaker":"Companheiro","effects":{"pressure":2,"ambition":2,"teammate_relation":1}},{"key":"share","label":"Admitir que depende do dia e perguntar como ele controla a própria ansiedade.","reply":"Tem dia que pesa mesmo. Eu tento desacelerar a respiração antes do lance.","result":"A conversa ficou mais pessoal do que competitiva.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"sociability":1,"pressure":-1}}]'::jsonb),
('mate_first_big_game','O tamanho do jogo entra na conversa','Um companheiro mais acostumado ao ambiente comenta que partidas mais pesadas parecem acelerar tudo nos primeiros minutos.',
'[{"key":"attack_early","label":"Dizer que prefere entrar no ritmo alto logo de cara.","reply":"Então usa os primeiros duelos para se colocar no jogo.","result":"Você escolheu enfrentar a intensidade de frente.","reply_speaker":"Companheiro","effects":{"ambition":2,"pressure":1,"fatigue":1}},{"key":"read_first","label":"Dizer que prefere usar os primeiros minutos para entender o comportamento do adversário.","reply":"Boa. Jogo grande também pune quem acelera sem ler.","result":"Você priorizou leitura antes de imposição.","reply_speaker":"Companheiro","effects":{"pressure":-1,"discipline":1,"ambition":-1}},{"key":"ask_story","label":"Perguntar qual foi o primeiro jogo em que ele realmente sentiu esse peso.","reply":"Foi quando eu errei dois passes simples e percebi que estava jogando contra o ambiente também.","result":"A orientação veio através de experiência pessoal.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"leadership":1}}]'::jsonb),
('mate_media_jealousy','A atenção externa ficou desigual','Um companheiro comenta que as últimas matérias estão falando muito mais de um de vocês do que do restante do grupo.',
'[{"key":"own_attention","label":"Dizer que exposição faz parte e que pretende aproveitar enquanto ela existe.","reply":"Justo. Só não deixa isso virar outro jogo aqui dentro.","result":"Você assumiu a visibilidade sem escondê-la.","reply_speaker":"Companheiro","effects":{"ambition":2,"ego":1,"teammate_relation":-2,"pressure":1}},{"key":"share_credit","label":"Dizer que pretende destacar o trabalho do grupo quando falar publicamente.","reply":"Isso muda bastante como a coisa chega no vestiário.","result":"A exposição foi tratada como algo coletivo.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"ego":-1,"ambition":-1}},{"key":"separate","label":"Dizer que imprensa e vestiário são ambientes diferentes e que prefere não misturar os dois.","reply":"É uma forma de lidar. Aqui dentro a gente vê quem entrega.","result":"Você colocou uma fronteira clara entre os ambientes.","reply_speaker":"Companheiro","effects":{"pressure":-1,"teammate_relation":0,"sociability":-1}}]'::jsonb),
('mate_support_bad_week','Ele percebeu uma semana difícil','Um companheiro nota que você está mais quieto e pergunta se quer falar sobre uma sequência de treinos e jogos abaixo do que esperava.',
'[{"key":"open","label":"Contar o que está te incomodando e ouvir a leitura dele.","reply":"Eu já passei por isso. Às vezes a gente tenta corrigir cinco coisas de uma vez.","result":"Você dividiu parte da pressão com alguém do elenco.","reply_speaker":"Companheiro","effects":{"teammate_relation":4,"pressure":-2,"sociability":1}},{"key":"work","label":"Dizer que prefere responder trabalhando e pedir que ele te cobre no treino.","reply":"Fechado. Se baixar o ritmo eu vou falar.","result":"A ajuda virou cobrança prática.","reply_speaker":"Companheiro","effects":{"ambition":2,"teammate_relation":2,"pressure":1}},{"key":"space","label":"Agradecer, mas dizer que hoje precisa organizar a cabeça sozinho.","reply":"Tranquilo. Se mudar de ideia, me chama.","result":"Você preservou espaço pessoal sem romper a relação.","reply_speaker":"Companheiro","effects":{"pressure":-1,"teammate_relation":0,"sociability":-1}}]'::jsonb),
('mate_goal_drought_support','A bola não está entrando','Um companheiro comenta que percebeu você procurando demais a finalização e pergunta se o jejum está entrando na sua cabeça.',
'[{"key":"keep_shooting","label":"Dizer que a saída é continuar chegando e finalizar ainda mais quando aparecer espaço.","reply":"Então não foge da próxima. Só escolhe bem onde gastar a chance.","result":"Você decidiu responder ao jejum com volume.","reply_speaker":"Companheiro","effects":{"ambition":2,"pressure":2,"teammate_relation":1}},{"key":"simplify","label":"Dizer que vai simplificar algumas jogadas até recuperar o tempo da finalização.","reply":"Pode ajudar. Um passe bom também te coloca de volta no jogo.","result":"Você decidiu reconstruir confiança por ações menos forçadas.","reply_speaker":"Companheiro","effects":{"pressure":-2,"ambition":-1,"discipline":1}},{"key":"study","label":"Pedir que ele reveja com você onde as chances estão nascendo e morrendo.","reply":"Vamos olhar. Talvez o problema esteja antes do chute.","result":"O jejum virou problema de leitura coletiva.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"leadership":1}}]'::jsonb),
('mate_private_confidence','Uma conversa inesperadamente pessoal','Um companheiro admite que também tem dias em que entra no treino achando que vai errar tudo.',
'[{"key":"reciprocate","label":"Contar uma situação em que você também sentiu isso.","reply":"É bom saber que não acontece só comigo.","result":"A relação ganhou uma camada mais pessoal.","reply_speaker":"Companheiro","effects":{"teammate_relation":4,"sociability":2}},{"key":"challenge_mindset","label":"Dizer que você tenta tratar insegurança como sinal para se concentrar mais.","reply":"Talvez eu consiga usar assim em vez de tentar expulsar a sensação.","result":"A conversa virou uma abordagem competitiva para a insegurança.","reply_speaker":"Companheiro","effects":{"ambition":2,"teammate_relation":1,"pressure":1}},{"key":"practical","label":"Perguntar qual parte do jogo dele muda primeiro quando a confiança cai.","reply":"Meu primeiro passe. Quando ele sai ruim, eu começo a esconder o jogo.","result":"Vocês transformaram emoção em observação concreta.","reply_speaker":"Companheiro","effects":{"leadership":1,"teammate_relation":2,"sociability":-1}}]'::jsonb),
('mate_mentor_advice','Um companheiro fala sobre carreira longa','Um jogador mais experiente comenta que evoluir rápido e aguentar uma temporada inteira são problemas diferentes.',
'[{"key":"push","label":"Dizer que, nesta fase, você aceita algum desgaste para acelerar sua evolução.","reply":"É uma escolha. Só aprende a reconhecer quando o corpo começa a cobrar.","result":"Você manteve uma estratégia agressiva de desenvolvimento.","reply_speaker":"Companheiro","effects":{"ambition":2,"fatigue":1,"pressure":1}},{"key":"balance","label":"Perguntar como ele aprendeu a alternar dias fortes e dias de manutenção.","reply":"Eu demorei para entender que treino leve também faz parte do treino.","result":"A conversa foi para gestão de carga.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"discipline":1,"ambition":-1}},{"key":"individual","label":"Dizer que prefere descobrir seu próprio limite e comparar sensações ao longo das semanas.","reply":"Também funciona, desde que você realmente preste atenção nos sinais.","result":"Você manteve autonomia sobre a própria rotina.","reply_speaker":"Companheiro","effects":{"pressure":-1,"teammate_relation":0,"leadership":1}}]'::jsonb),
('mate_recovery_warning','Seu cansaço ficou visível','Um companheiro percebe que você demorou mais para recuperar depois de uma sequência intensa e pergunta se vai reduzir o ritmo.',
'[{"key":"recover","label":"Dizer que vai baixar a carga antes do próximo treino forte.","reply":"Boa. Melhor perder uma repetição do que perder três dias.","result":"Você escolheu preservar capacidade para os próximos dias.","reply_speaker":"Companheiro","effects":{"fatigue":-2,"ambition":-1,"teammate_relation":1}},{"key":"maintain","label":"Dizer que vai manter a carga, mas cortar ações extras fora do treino coletivo.","reply":"É um meio-termo. O importante é não somar tudo sem perceber.","result":"Você redistribuiu o esforço em vez de simplesmente reduzir.","reply_speaker":"Companheiro","effects":{"discipline":1,"pressure":1}},{"key":"push_test","label":"Dizer que quer testar até onde aguenta antes de ajustar a rotina.","reply":"Então pelo menos não ignora se o corpo mudar amanhã.","result":"Você escolheu explorar o limite físico.","reply_speaker":"Companheiro","effects":{"ambition":2,"fatigue":2,"pressure":1}}]'::jsonb),
('mate_routine_question','Ele quer saber sua rotina','Um companheiro pergunta o que você costuma fazer entre o fim do treino e o dia seguinte para chegar inteiro de novo.',
'[{"key":"strict","label":"Contar que prefere uma rotina rígida e repetir quase sempre os mesmos horários.","reply":"Eu nunca consegui ser tão certinho, mas dá para ver a vantagem.","result":"Vocês compararam estilos de disciplina diferentes.","reply_speaker":"Companheiro","effects":{"discipline":2,"sociability":-1,"teammate_relation":1}},{"key":"flexible","label":"Dizer que adapta descanso e lazer de acordo com como o corpo respondeu ao dia.","reply":"Faz sentido. Tem treino que pede cama e tem treino que não pesa nada.","result":"A rotina foi tratada como ajuste contínuo.","reply_speaker":"Companheiro","effects":{"pressure":-1,"teammate_relation":2}},{"key":"exchange","label":"Perguntar a rotina dele e comparar o que cada um poderia testar por uma semana.","reply":"Vamos fazer e depois comparar como chegamos no próximo treino.","result":"A conversa virou uma pequena experiência entre vocês.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"sociability":1,"ambition":1}}]'::jsonb),
('mate_ask_help','Um companheiro pede sua ajuda','Depois da atividade, um jogador do elenco pergunta se você pode ajudá-lo a repetir uma situação em que vem tendo dificuldade.',
'[{"key":"coach_him","label":"Ficar alguns minutos e observar as repetições dele de fora.","reply":"Valeu. Fala quando eu repetir o mesmo erro.","result":"Você assumiu um papel de observador e parceiro.","reply_speaker":"Companheiro","effects":{"teammate_relation":4,"leadership":2,"fatigue":1}},{"key":"compete","label":"Transformar o exercício em uma disputa para os dois repetirem sob pressão.","reply":"Melhor ainda. Se valer ponto eu vou levar mais a sério.","result":"A ajuda virou competição produtiva.","reply_speaker":"Companheiro","effects":{"ambition":2,"rivalry":1,"teammate_relation":1,"fatigue":2}},{"key":"reschedule","label":"Dizer que hoje não vai ficar, mas combinar de fazer no próximo treino leve.","reply":"Fechado. Eu te lembro quando acabar a sessão.","result":"A ajuda foi adiada sem ser recusada de vez.","reply_speaker":"Companheiro","effects":{"fatigue":-1,"teammate_relation":0,"sociability":-1}}]'::jsonb),
('mate_social_invite','O grupo combina algo fora do clube','Um companheiro te chama para encontrar alguns jogadores depois do treino e diz que não vai ser nada ligado a futebol.',
'[{"key":"go","label":"Aceitar e aproveitar para conhecer o grupo fora do ambiente do clube.","reply":"Boa. Lá ninguém vai falar de tática, prometo.","result":"Você escolheu investir no convívio fora de campo.","reply_speaker":"Companheiro","effects":{"teammate_relation":4,"sociability":2,"fatigue":1}},{"key":"short_visit","label":"Dizer que aparece por pouco tempo e depois segue sua própria rotina.","reply":"Já vale. Passa lá nem que seja só para dar um oi.","result":"Você conciliou convívio e rotina pessoal.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"sociability":1}},{"key":"stay_home","label":"Recusar desta vez e dizer que quer uma noite mais quieta.","reply":"Tranquilo. Na próxima eu chamo de novo.","result":"Você preservou sua rotina sem transformar a recusa em conflito.","reply_speaker":"Companheiro","effects":{"fatigue":-1,"pressure":-1,"sociability":-1,"teammate_relation":0}}]'::jsonb),
('mate_prank','Uma brincadeira cai no seu colo','No vestiário, um companheiro faz uma brincadeira com você e espera para ver como você reage.',
'[{"key":"return","label":"Entrar na brincadeira e devolver outra na mesma hora.","reply":"Agora ficou elas por elas.","result":"A provocação virou troca de humor.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"sociability":2,"pressure":1}},{"key":"deadpan","label":"Responder sério por alguns segundos e só depois mostrar que entendeu a piada.","reply":"Eu achei que tinha passado do ponto por um segundo.","result":"Você deixou o clima no limite entre tensão e humor.","reply_speaker":"Companheiro","effects":{"teammate_relation":1,"ego":1}},{"key":"not_today","label":"Dizer que hoje não está no clima e seguir se arrumando.","reply":"Beleza, hoje eu deixo quieto.","result":"Você estabeleceu um limite sem prolongar o episódio.","reply_speaker":"Companheiro","effects":{"pressure":-1,"sociability":-1,"teammate_relation":-1}}]'::jsonb),
('mate_social_post','Ele quer postar uma foto de vocês','Um companheiro sugere publicar uma foto dos dois depois do treino e marcar o perfil do clube.',
'[{"key":"post","label":"Aceitar e deixar a legenda por conta dele.","reply":"Boa. Vou pegar aquela foto do fim do treino.","result":"Você entrou espontaneamente na exposição conjunta.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"sociability":2,"pressure":1}},{"key":"control","label":"Aceitar, mas sugerir uma foto e uma legenda mais discretas.","reply":"Fechado. Sem exagerar na legenda.","result":"Você participou mantendo mais controle da imagem.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"discipline":1}},{"key":"private","label":"Dizer que prefere não misturar tanto treino com rede social.","reply":"Tranquilo. Eu posto só a minha então.","result":"Você manteve uma separação maior entre rotina e exposição.","reply_speaker":"Companheiro","effects":{"pressure":-1,"sociability":-1,"teammate_relation":0}}]'::jsonb),
('mate_music_room','O vestiário discute a música','Antes da atividade, um companheiro pega a caixa de som e pergunta se você quer escolher a próxima sequência de músicas.',
'[{"key":"take_over","label":"Assumir a playlist e colocar o que você usa para entrar no clima.","reply":"Então hoje a responsabilidade da música é sua.","result":"Você ocupou mais espaço no ambiente do grupo.","reply_speaker":"Companheiro","effects":{"sociability":2,"ego":1,"teammate_relation":1}},{"key":"share","label":"Pedir para cada jogador escolher uma música e montar uma fila coletiva.","reply":"Boa. Assim ninguém reclama que só toca uma coisa.","result":"A escolha virou dinâmica do grupo.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"leadership":1,"ego":-1}},{"key":"headphones","label":"Dizer que prefere ficar no fone e manter sua preparação individual.","reply":"Fechado. Depois eu te mando a playlist mesmo assim.","result":"Você preservou uma rotina mais individual.","reply_speaker":"Companheiro","effects":{"pressure":-1,"sociability":-1,"teammate_relation":0}}]'::jsonb),
('mate_contract_money','O assunto chega ao dinheiro','Um companheiro comenta que jogadores da mesma categoria recebem condições diferentes e pergunta se você costuma falar sobre contrato dentro do elenco.',
'[{"key":"open","label":"Dizer que comparar condições pode ajudar os jogadores a entender o próprio valor.","reply":"Também acho. O clube sabe tudo sobre a gente e a gente quase não sabe nada.","result":"A conversa ficou mais aberta sobre mercado e valor.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"ambition":1,"pressure":1}},{"key":"private","label":"Dizer que prefere manter números e negociação entre você e quem cuida da sua carreira.","reply":"Justo. Tem coisa que vira ruído rápido no vestiário.","result":"Você estabeleceu uma fronteira profissional clara.","reply_speaker":"Companheiro","effects":{"discipline":1,"teammate_relation":0,"sociability":-1}},{"key":"ask_role","label":"Evitar valores e perguntar como ele avalia a própria situação no elenco.","reply":"Meu problema nem é só dinheiro. Quero saber onde o clube me vê daqui a um ano.","result":"O assunto mudou de salário para perspectiva esportiva.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"leadership":1,"ambition":-1}}]'::jsonb),
('mate_agent_rumor','Um rumor chega pelo vestiário','Um companheiro diz que ouviu seu nome ligado a outro clube e pergunta se seu empresário está mexendo em alguma coisa.',
'[{"key":"play_along","label":"Dizer que movimento de mercado é normal e deixar a possibilidade no ar.","reply":"Então tem fumaça. O vestiário vai falar disso a semana inteira.","result":"Você não confirmou nada, mas alimentou a curiosidade.","reply_speaker":"Companheiro","effects":{"ambition":2,"ego":1,"pressure":2,"teammate_relation":1}},{"key":"close_topic","label":"Dizer que enquanto estiver ali sua cabeça está na equipe atual.","reply":"Certo. Então eu não vou ficar especulando.","result":"Você fechou o assunto com uma posição profissional.","reply_speaker":"Companheiro","effects":{"discipline":2,"pressure":-1,"ambition":-1}},{"key":"ask_source","label":"Perguntar de onde veio o rumor sem comentar seu conteúdo.","reply":"Foi de um cara que conhece gente da base. Pode ser nada também.","result":"Você buscou informação sem se comprometer com a história.","reply_speaker":"Companheiro","effects":{"teammate_relation":2,"pressure":1,"sociability":-1}}]'::jsonb),
('mate_captain_standard','Um jogador experiente cobra padrão','Um dos jogadores mais experientes diz que o grupo está deixando pequenos detalhes de treino escaparem e pergunta como você acha que deveriam reagir.',
'[{"key":"raise_voice","label":"Dizer que alguém precisa cobrar na hora, mesmo que o clima fique mais pesado.","reply":"É a minha tendência também. Só precisa saber quando apertar.","result":"Você apoiou uma liderança mais direta.","reply_speaker":"Companheiro experiente","effects":{"leadership":2,"pressure":1,"teammate_relation":1}},{"key":"self_police","label":"Propor que cada setor defina seus próprios padrões e se cobre internamente.","reply":"Isso distribui a responsabilidade. Pode funcionar melhor do que uma voz só.","result":"Você sugeriu uma liderança distribuída.","reply_speaker":"Companheiro experiente","effects":{"leadership":1,"teammate_relation":2,"discipline":1}},{"key":"protect_flow","label":"Dizer que nem todo erro precisa virar cobrança para o treino não ficar travado.","reply":"Também tem isso. Cobrança demais vira medo de errar.","result":"Você priorizou fluidez e ambiente sobre vigilância constante.","reply_speaker":"Companheiro experiente","effects":{"pressure":-2,"discipline":-1,"teammate_relation":1}}]'::jsonb),
('mate_leadership_test','O grupo espera uma reação','Depois de uma sequência ruim no treino, dois companheiros começam a discutir e um deles olha para você esperando uma posição.',
'[{"key":"intervene","label":"Interromper e pedir que os dois refaçam a jogada antes de continuar a discussão.","reply":"Tá. Faz de novo e depois a gente fala.","result":"Você puxou o conflito de volta para o campo.","reply_speaker":"Companheiro","effects":{"leadership":2,"pressure":1,"teammate_relation":1}},{"key":"pick_side","label":"Dizer qual leitura do lance você considera correta e explicar o motivo.","reply":"Pelo menos agora tem uma referência. Vamos testar.","result":"Você assumiu posição técnica e correu o risco de contrariar alguém.","reply_speaker":"Companheiro","effects":{"ambition":1,"leadership":1,"teammate_relation":-1,"pressure":1}},{"key":"let_resolve","label":"Dizer que os dois precisam resolver a comunicação entre eles sem transformar o grupo em árbitro.","reply":"Certo. A gente fecha isso depois do exercício.","result":"Você evitou centralizar uma disputa que não era sua.","reply_speaker":"Companheiro","effects":{"pressure":-1,"leadership":-1,"teammate_relation":1}}]'::jsonb)
)
INSERT INTO private.career_event_templates(event_key,source,title,body,choices)
SELECT event_key,'teammate',title,body,choices FROM templates
ON CONFLICT(event_key) DO UPDATE SET source=excluded.source,title=excluded.title,body=excluded.body,choices=excluded.choices;

UPDATE private.career_event_templates
SET title='A concorrência entra na conversa',
    body='Um jogador do elenco comenta que vocês estão buscando espaço ao mesmo tempo e pergunta como você enxerga essa concorrência.',
    choices='[{"key":"competitive","label":"Dizer que quer uma disputa intensa e que ninguém precisa aliviar no treino.","reply":"Então combinado. Quem estiver melhor vai ter que mostrar toda semana.","result":"A concorrência ficou mais explícita.","reply_speaker":"Companheiro","effects":{"ambition":2,"pressure":1,"rivalry":1,"teammate_relation":-1}},{"key":"cooperate","label":"Propor que vocês troquem leitura e se cobrem, mesmo disputando minutos.","reply":"Dá para competir e ainda melhorar junto. Vamos ver se funciona.","result":"A disputa ganhou um componente de cooperação.","reply_speaker":"Companheiro","effects":{"teammate_relation":3,"ambition":-1}},{"key":"pragmatic","label":"Dizer que prefere deixar a comissão decidir e focar nas próprias tarefas.","reply":"Justo. No fim a escalação não é nossa decisão mesmo.","result":"Você manteve a relação mais profissional e distante.","reply_speaker":"Companheiro","effects":{"pressure":-1,"discipline":1,"teammate_relation":0}}]'::jsonb
WHERE event_key='teammate_locker_room';